const byId = new Map(CUSTOMERS.map(customer=>[customer.id,customer]));
export function customerForRound(index=0){
 const round=Number.isFinite(index)?Math.max(0,Math.floor(index)):0;
 return CUSTOMERS[round%CUSTOMERS.length];
}
export function customerForOrder(order){return byId.get(order?.customerId)||CUSTOMERS[0];}
